// ─────────────────────────────────────────────────────────────────────────────

// Email failure tracking (replaces MongoDB email_failure_events)
export const emailFailureEvents = sqliteTable('email_failure_events', {
  id: text('id').primaryKey(),
  recipient: text('recipient'),
  errorCode: text('error_code'),
  detail: text('detail'),
  expiresAt: integer('expires_at').notNull(),                         // 1 hour TTL
  createdAt: integer('created_at').default(sql`(unixepoch())`),
}, (t) => [
  index('efe_expires_idx').on(t.expiresAt),
]);

// Alert state singleton
export const emailAlertState = sqliteTable('email_alert_state', {
  id: text('id').primaryKey().default('singleton'),
  alertActive: integer('alert_active').default(0),
  lastAlertAt: integer('last_alert_at'),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
});

export const ragReindexJobs = sqliteTable('rag_reindex_jobs', {
  id: text('id').primaryKey(),
  actorId: text('actor_id'),
  status: text('status').notNull().default('pending'),
  requestedScopes: text('requested_scopes').notNull().default('["notes"]'),
  items: text('items').notNull().default('[]'),
  errorLog: text('error_log'),
  leaseToken: text('lease_token'),
  leaseExpiresAt: integer('lease_expires_at'),
  createdAt: integer('created_at').default(sql`(unixepoch())`),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
  completedAt: integer('completed_at'),
}, (t) => [
  index('rrj_status_updated_idx').on(t.status, t.updatedAt),
]);

export const destructivePreviewTokens = sqliteTable('destructive_preview_tokens', {
  id: text('id').primaryKey(),
  actorId: text('actor_id').notNull(),
  chapterIds: text('chapter_ids').notNull(),
  impactHash: text('impact_hash').notNull(),
  expiresAt: integer('expires_at').notNull(),
  consumedAt: integer('consumed_at'),
  createdAt: integer('created_at').default(sql`(unixepoch())`),
});

// Every scheduled invocation has one immutable execution record. The singleton
// state gives an operator a durable indication of the current cron failure
// condition without relying on an external alerting provider.
export const cronRuns = sqliteTable('cron_runs', {
  id: text('id').primaryKey(),
  cronExpression: text('cron_expression').notNull(),
  scheduledAt: integer('scheduled_at').notNull(),
  startedAt: integer('started_at').notNull(),
  completedAt: integer('completed_at'),
  status: text('status').notNull(),                                    // running | succeeded | failed
  failureCount: integer('failure_count').notNull().default(0),
  errorSummary: text('error_summary'),
}, (t) => [
  index('cron_runs_expression_scheduled_idx').on(t.cronExpression, t.scheduledAt),
  index('cron_runs_status_started_idx').on(t.status, t.startedAt),
]);

export const cronAlertState = sqliteTable('cron_alert_state', {
  id: text('id').primaryKey().default('singleton'),
  alertActive: integer('alert_active').notNull().default(0),
  consecutiveFailures: integer('consecutive_failures').notNull().default(0),
  lastFailureAt: integer('last_failure_at'),
  lastSuccessAt: integer('last_success_at'),
  lastAlertAt: integer('last_alert_at'),
  alertReason: text('alert_reason'),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
});

// Latest result from the GitHub Cloudflare Analytics contract probe. The
// workflow is the source of the probe; this singleton is the Worker-owned
// handoff consumed by the admin health banner.
export const cloudflareAnalyticsHealth = sqliteTable('cloudflare_analytics_health', {
  id: text('id').primaryKey().default('singleton'),
  status: text('status').notNull(),                                    // healthy | unhealthy
  checkedAt: text('checked_at').notNull(),
  error: text('error'),
  remediation: text('remediation'),
  needsRotation: integer('needs_rotation').notNull().default(0),
  hourlyBucketsReturned: integer('hourly_buckets_returned').notNull().default(0),
  hourlyBucketCount: integer('hourly_bucket_count'),
  uniqueVisitorsSupported: integer('unique_visitors_supported'),
  consecutiveFailures: integer('consecutive_failures').notNull().default(0),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
});

// Dead letter queue (failed async jobs)
export const deadLetters = sqliteTable('dead_letters', {
  id: text('id').primaryKey(),
  jobType: text('job_type').notNull(),
  payload: text('payload').default('{}'),
  error: text('error'),
  attempts: integer('attempts').default(1),
  expiresAt: integer('expires_at').notNull(),                         // 30d TTL
  createdAt: integer('created_at').default(sql`(unixepoch())`),
}, (t) => [
  index('dl_expires_idx').on(t.expiresAt),
]);

// Admin config key-value store
export const adminConfig = sqliteTable('admin_config', {
  key: text('key').primaryKey(),
  value: text('value'),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
});

// Memory brain (per-user AI memory)
export const memoryBrain = sqliteTable('memory_brain', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull(),
  key: text('key').notNull(),
  value: text('value'),
  updatedAt: integer('updated_at').default(sql`(unixepoch())`),
}, (t) => [
  uniqueIndex('mb_user_key_idx').on(t.userId, t.key),
]);

// Migrations bookkeeping (replaces schema_versions)
export const schemaMigrations = sqliteTable('schema_migrations', {
  version: text('version').primaryKey(),
  appliedAt: integer('applied_at').default(sql`(unixepoch())`),
});
